class Solution {
  private int[] parent;

  public boolean areSentencesSimilarTwo(
      String[] sentence1, String[] sentence2, List<List<String>> similarPairs) {
    if (sentence1.length != sentence2.length) return false;
    Map<String, Integer> id = new HashMap<>();
    for (List<String> pair : similarPairs) {
      for (String w : pair) id.putIfAbsent(w, id.size());
    }
    parent = new int[id.size()];
    for (int i = 0; i < parent.length; i++) parent[i] = i;
    for (List<String> pair : similarPairs)
      parent[find(id.get(pair.get(0)))] = find(id.get(pair.get(1)));
    for (int i = 0; i < sentence1.length; i++) {
      if (sentence1[i].equals(sentence2[i])) continue;
      Integer a = id.get(sentence1[i]), b = id.get(sentence2[i]);
      if (a == null || b == null || find(a) != find(b)) return false;
    }
    return true;
  }

  private int find(int x) {
    while (parent[x] != x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }
}
